/* Map ROM bank ID to array index */
static inline int audio_bank_to_index(uint8_t bank) {
    switch (bank) {
        case 0x0F: return 0;
        case 0x10: return 1;
        case 0x11: return 2;
        case 0x12: return 3;
        case 0x13: return 4;
        default: return 0;
    }
}

